{
  "items": [
    {
      "name": "Finset.sum_range_id_mul_two",
      "module_name": "Mathlib.Algebra.BigOperators.Intervals",
      "kind": "theorem",
      "type": "∀ (n : ℕ), (∑ i ∈ Finset.range n, i) * 2 = n * (n - 1)"
    },
    {
      "name": "Finset.sum_range_id",
      "module_name": "Mathlib.Algebra.BigOperators.Intervals",
      "kind": "theorem",
      "type": "∀ (n : ℕ), ∑ i ∈ Finset.range n, i = n * (n - 1) / 2"
    },
    {
      "name": "Nat.triangle_succ",
      "module_name": "Mathlib.Data.Nat.Choose.Basic",
      "kind": "theorem",
      "type": "∀ (n : ℕ), (n + 1) * (n + 1 - 1) / 2 = n * (n - 1) / 2 + n"
    },
    {
      "name": "Nat.choose_two_right",
      "module_name": "Mathlib.Data.Nat.Choose.Basic",
      "kind": "theorem",
      "type": "∀ (n : ℕ), n.choose 2 = n * (n - 1) / 2"
    },
    {
      "name": "Nat.two_mul_odd_div_two",
      "module_name": "Mathlib.Data.Nat.Init",
      "kind": "theorem",
      "type": "∀ {n : ℕ}, n % 2 = 1 → 2 * (n / 2) = n - 1"
    },
    {
      "name": "Nat.geomSum_eq",
      "module_name": "Mathlib.Algebra.Ring.GeomSum",
      "kind": "theorem",
      "type": "∀ {m : ℕ}, 2 ≤ m → ∀ (n : ℕ), ∑ k ∈ Finset.range n, m ^ k = (m ^ n - 1) / (m - 1)"
    }
  ]
}
